            axi4_master_wr_burst_cnt_reg_next = 8'b11111111;
          end
          else begin
            axi4_master_wr_burst_cnt_reg_next = axi4_master_wr_wr_len_reg[7:0];
          end
          wr_fifo_ack = 1'b0;
          wr_transfer = 1'b0;
        end
      8'd2 :
        begin
          if (( ~ out_fifo_afull) && axi4_master_wr_wr_valid) begin
            axi4_master_wr_wvalid_reg_next = 1'b1;
            wr_fifo_ack = 1'b1;
            if (axi4_master_wr_burst_cnt_reg == 8'b00000000) begin
              axi4_master_wr_wlast_reg_next = 1'b1;
              axi4_master_wr_wr_dstate_next = 8'd3;
              axi4_master_wr_data_done_reg_next = 1'b1;
            end
            axi4_master_wr_burst_cnt_reg_next = axi4_master_wr_burst_cnt_reg - 8'b00000001;
          end
          else begin
            axi4_master_wr_wvalid_reg_next = 1'b0;
            wr_fifo_ack = 1'b0;
          end
          wr_transfer = 1'b1;
        end
      8'd3 :
        begin
          if (axi4_master_wr_addr_done_reg_temp) begin
            if (axi4_master_wr_last_burst_reg_temp) begin
              axi4_master_wr_wr_dstate_next = 8'd0;
            end
            else begin
              axi4_master_wr_wr_dstate_next = 8'd1;
            end
          end
          axi4_master_wr_wvalid_reg_next = 1'b0;
          axi4_master_wr_wlast_reg_next = 1'b0;
          wr_fifo_ack = 1'b0;
          wr_transfer = 1'b0;
          axi4_master_wr_data_done_reg_next = 1'b1;
        end
      default :
        begin
          wr_fifo_ack = 1'b0;
          wr_transfer = 1'b0;
          axi4_master_wr_wr_dstate_next = 8'd0;
        end
    endcase
    Deep_Learning_interface_Wr_AWVALID_1 = axi4_master_wr_awvalid_reg;
    Deep_Learning_interface_Wr_AWADDR_1 = axi4_master_wr_awaddr_reg;
    Deep_Learning_interface_Wr_AWLEN_1 = axi4_master_wr_awlen_reg;
    Deep_Learning_interface_Wr_AWID_1 = axi4_master_wr_awid_reg;
    out_fifo_push = axi4_master_wr_wvalid_reg;
    out_fifo_wlast = axi4_master_wr_wlast_reg;
    axi4_master_wr_last_burst_reg_next = axi4_master_wr_last_burst_reg_temp;
    axi4_master_wr_addr_done_reg_next = axi4_master_wr_addr_done_reg_temp;
  end

  assign const_awsize = 3'b010;

  assign Deep_Learning_interface_Wr_AWSIZE = const_awsize;

  assign const_1_2 = 2'b01;

  assign Deep_Learning_interface_Wr_AWBURST = const_1_2;

  assign const_0_1 = 1'b0;

  assign Deep_Learning_interface_Wr_AWLOCK = const_0_1;

  assign const_3_4 = 4'b0011;

  assign Deep_Learning_interface_Wr_AWCACHE = const_3_4;

  assign const_0_3 = 3'b000;

  assign Deep_Learning_interface_Wr_AWPROT = const_0_3;

  assign const_wstrb = 4'b1111;

  assign Deep_Learning_interface_Wr_WSTRB = const_wstrb;

  Modulatio_ip_wlast_fifo u_Modulatio_ip_wlast_fifo_inst (.clk(clk),
                                                          .reset(reset),
                                                          .enb(const_1_1),
                                                          .In(out_fifo_wlast),  // ufix1
                                                          .Push(out_fifo_push),  // ufix1
                                                          .Pop(out_fifo_ack),  // ufix1
                                                          .Out(Deep_Learning_interface_Wr_WLAST)  // ufix1
                                                          );

  assign Deep_Learning_interface_Wr_WVALID = wvalid_internal;

  assign Deep_Learning_interface_Wr_BREADY = const_1_1;

  assign user_wr_complete = wr_complete_internal;

  assign aw_transfer = Deep_Learning_interface_Wr_AWREADY & Deep_Learning_interface_Wr_AWVALID_1;

  assign const_0_9 = 9'b000000000;

  assign const_1_9 = 9'b000000001;

  assign aw_transfer_len = (aw_transfer == 1'b0 ? const_0_9 :
              const_1_9);

  assign w_transfer = const_1_1 & Deep_Learning_interface_Wr_BVALID;

  assign w_transfer_len = (w_transfer == 1'b0 ? const_0_9 :
              const_1_9);

  assign accum_awlen_adder_1 = {23'b0, aw_transfer_len};
  assign accum_aw_len = accum_awlen_adder_1 + accum_value;

  assign accum_wlen_adder_1 = {23'b0, w_transfer_len};
  assign accum_w_len = accum_aw_len - accum_wlen_adder_1;

  always @(posedge clk or posedge reset)
    begin : reg_accum_process
      if (reset == 1'b1) begin
        accum_value <= 32'sb00000000000000000000000000000000;
      end
      else begin
        if (enb) begin
          accum_value <= accum_w_len;
        end
      end
    end

  assign in_burst_deep_learning_interface_wr = accum_value > 32'sb00000000000000000000000000000000;

  assign Deep_Learning_interface_Wr_AWID = Deep_Learning_interface_Wr_AWID_1;

  assign Deep_Learning_interface_Wr_AWADDR = Deep_Learning_interface_Wr_AWADDR_1;

  assign Deep_Learning_interface_Wr_AWLEN = Deep_Learning_interface_Wr_AWLEN_1;

  assign Deep_Learning_interface_Wr_AWVALID = Deep_Learning_interface_Wr_AWVALID_1;

endmodule  // Modulatio_ip_deep_learning_interface_wr

